def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([1, 2]), fmt([2, 1]), fmt([4, 4, 4]), fmt([1, 2, 3]), fmt([3, 2, 1]),
             fmt([1, 1, 2]), fmt([1, 2, 1]), fmt([2, 1, 1]), fmt([1, 1, 2, 2]), fmt([2, 2, 1, 1]), fmt([1, 2, 2, 1])]
    for n in (2, 3, 4, 5, 6, 7):
        for _ in range(5):
            k = rng.choice([2, 3, 10])
            a = [rng.randint(1, k) for _ in range(n)]
            if rng.random() < 0.3:
                a = sorted(a)
            if rng.random() < 0.2:
                a = sorted(a, reverse=True)
            tests.append(fmt(a))
    big = 100000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(big)]))
    tests.append(fmt(list(range(1, big + 1))))
    tests.append(fmt([7] * big))
    tests.append(fmt([1] * (big - 1) + [2]))
    return tests

